/* Helper for COMMAND(S) command
 *
 * COMMAND(S) GETKEYS arg0 arg1 arg2 ... */
void getKeysSubcommand(client *c) {
    struct redisCommand *cmd = NULL;
    getKeysResult result = GETKEYS_RESULT_INIT;
    int j, keys_ok = 0;
    int cmd_argc = c->argc - 2;
    robj **cmd_argv = c->argv + 2;
    dict *commands;
    dictEntry *he, *sub_he;
    struct redisCommand *base_cmd;
    int num, numkeys, *keys;
    int first, last, step, idx, available;
    int i, found_store;
    int cmd_arity;
    uint64_t cmd_flags;
    redisGetKeysProc *keyproc;
    int out_n, argv_index;
    robj *keyobj;
    int firstKeyOfs, keyStep, keyCountOfs;
    int range_first, range_lastkey, range_step, abs_last, range_count;

    if (cmd_argc >= 1) {
        if (cmd_argv[0] != NULL) {
            commands = server.commands;
            if (commands != NULL) {
                he = dictFind(commands, cmd_argv[0]->ptr);
                if (he != NULL) {
                    base_cmd = dictGetVal(he);
                    if (base_cmd != NULL) {
                        if (cmd_argc > 1 && base_cmd->subcommands_dict != NULL) {
                            sub_he = dictFind(base_cmd->subcommands_dict, cmd_argv[1]->ptr);
                            cmd = sub_he ? dictGetVal(sub_he) : NULL;
                        } else {
                            cmd = base_cmd;
                        }
                    }
                }
            }
        }
    }

    if (!cmd) {
        addReplyError(c,"Invalid command specified");
        return;
    } else if (cmd->getkeys_proc == NULL && cmd->key_specs_num == 0) {
        addReplyError(c,"The command has no key arguments");
        return;
    } else if ((cmd->arity > 0 && cmd->arity != cmd_argc) ||
               (cmd_argc < -cmd->arity))
    {
        addReplyError(c,"Invalid number of arguments specified for command");
        return;
    }

    cmd_arity = cmd->arity;
    cmd_flags = cmd->flags;
    keyproc = cmd->getkeys_proc;
    firstKeyOfs = 3;
    keyStep = 1;
    keyCountOfs = 2;
    range_first = 0;
    range_lastkey = 0;
    range_step = 1;
    abs_last = 0;
    range_count = 0;
    found_store = 0;

    if (cmd_flags & CMD_MODULE_GETKEYS) {
        keys_ok = moduleGetCommandKeysViaAPI(cmd,cmd_argv,cmd_argc,&result);
    } else if (!(cmd_flags & CMD_MODULE) && keyproc) {
        if (keyproc == evalGetKeys) {
            num = atoi(cmd_argv[keyCountOfs]->ptr);
            available = (cmd_argc - firstKeyOfs)/keyStep;
            if (num < 1 || num > available) {
                result.numkeys = 0;
                keys_ok = 0;
            } else {
                numkeys = num;
                keys = getKeysPrepareResult(&result, numkeys);
                result.numkeys = numkeys;
                for (j = 0; j < num; j++) {
                    keys[j] = firstKeyOfs+(j*keyStep);
                }
                keys_ok = result.numkeys;
            }
        } else if (keyproc == sortGetKeys) {
            struct {
                char *name;
                int skip;
            } skiplist[] = {
                {"limit", 2},
                {"get", 1},
                {"by", 1},
                {NULL, 0}
            };
            num = 0;
            keys = getKeysPrepareResult(&result, 2);
            keys[num++] = 1;
            for (i = 2; i < cmd_argc; i++) {
                for (j = 0; skiplist[j].name != NULL; j++) {
                    if (!strcasecmp(cmd_argv[i]->ptr,skiplist[j].name)) {
                        i += skiplist[j].skip;
                        break;
                    } else if (!strcasecmp(cmd_argv[i]->ptr,"store") && i+1 < cmd_argc) {
                        found_store = 1;
                        keys[num] = i+1;
                        break;
                    }
                }
            }
            result.numkeys = num + found_store;
            keys_ok = result.numkeys;
        } else {
            keys_ok = keyproc(cmd,cmd_argv,cmd_argc,&result);
        }
    } else {
        if (cmd->legacy_range_key_spec.begin_search_type == KSPEC_BS_INVALID) {
            result.numkeys = 0;
            keys_ok = 0;
        } else {
            range_first = cmd->legacy_range_key_spec.bs.index.pos;
            range_lastkey = cmd->legacy_range_key_spec.fk.range.lastkey;
            range_step = cmd->legacy_range_key_spec.fk.range.keystep;
            first = range_first;
            last = range_lastkey;
            step = range_step;
            if (last >= 0) {
                abs_last = last + first;
                last = abs_last;
            }
            if (last < 0) {
                last = cmd_argc+last;
            }
            range_count = ((last - first)+1);
            keys = getKeysPrepareResult(&result, range_count);
            idx = 0;
            for (j = first; j <= last; j += step) {
                if (j >= cmd_argc) {
                    if (cmd_flags & CMD_MODULE || cmd_arity < 0) {
                        result.numkeys = 0;
                        keys_ok = 0;
                        idx = 0;
                        break;
                    } else {
                        serverPanic("Redis built-in command declared keys positions not matching the arity requirements.");
                    }
                }
                keys[idx++] = j;
            }
            if (idx > 0) {
                result.numkeys = idx;
                keys_ok = idx;
            }
        }
    }

    if (!keys_ok) {
        addReplyError(c,"Invalid arguments specified for command");
    } else {
        out_n = result.numkeys;
        addReplyArrayLen(c,out_n);
        for (j = 0; j < out_n; j++) {
            argv_index = result.keys[j]+2;
            keyobj = c->argv[argv_index];
            addReplyBulk(c,keyobj);
        }
    }
    getKeysFreeResult(&result);
}

/* COMMAND (no args) */
void commandCommand(client *c) {
    dictIterator *di;
    dictEntry *de;

    addReplyArrayLen(c, dictSize(server.commands));
    di = dictGetIterator(server.commands);
    while ((de = dictNext(di)) != NULL) {
        addReplyCommand(c, dictGetVal(de));
    }
    dictReleaseIterator(di);
}

/* COMMAND COUNT */
void commandCountCommand(client *c) {
    addReplyLongLong(c, dictSize(server.commands));
}

typedef enum {
    COMMAND_LIST_FILTER_MODULE,
    COMMAND_LIST_FILTER_ACLCAT,
    COMMAND_LIST_FILTER_PATTERN,
} commandListFilterType;

typedef struct {
    commandListFilterType type;
    sds arg;
    struct {
        int valid;
        union {
            uint64_t aclcat;
            void *module_handle;
        } u;
    } cache;
} commandListFilter;

int shouldFilterFromCommandList(struct redisCommand *cmd, commandListFilter *filter) {
    switch (filter->type) {
        case (COMMAND_LIST_FILTER_MODULE):
            if (!filter->cache.valid) {
                filter->cache.u.module_handle = moduleGetHandleByName(filter->arg);
                filter->cache.valid = 1;
            }
            return !moduleIsModuleCommand(filter->cache.u.module_handle, cmd);
        case (COMMAND_LIST_FILTER_ACLCAT): {
            if (!filter->cache.valid) {
                filter->cache.u.aclcat = ACLGetCommandCategoryFlagByName(filter->arg);
                filter->cache.valid = 1;
            }
            uint64_t cat = filter->cache.u.aclcat;
            if (cat == 0)
                return 1; /* Invalid ACL category */
            return (!(cmd->flags & cat));
            break;
        }
        case (COMMAND_LIST_FILTER_PATTERN):
            return !stringmatchlen(filter->arg, sdslen(filter->arg), cmd->name, strlen(cmd->name), 1);
        default:
            serverPanic("Invalid filter type %d", filter->type);
    }
}

